"""Unit-aware calculations. Python 3.14+, standard library only."""
import math

def finite(value):
    if type(value) not in (int, float) or not math.isfinite(value):
        raise ValueError("finite number required")
    return value

def rate(count, seconds):
    count, seconds = finite(count), finite(seconds)
    if count < 0 or seconds <= 0:
        raise ValueError("nonnegative count and positive seconds required")
    return count / seconds

def relative_change(old, new):
    old, new = finite(old), finite(new)
    if old <= 0 or new < 0:
        raise ValueError("positive base and nonnegative new count required")
    return (new - old) / old

def combined_rate(counts, durations):
    if not counts or len(counts) != len(durations):
        raise ValueError("nonempty matching observations required")
    for count, seconds in zip(counts, durations):
        rate(count, seconds)
    return rate(sum(counts), sum(durations))

if __name__ == "__main__":
    print(combined_rate([100,100], [10,30]))
    print(relative_change(50,40))

"""Descriptive summaries and a deliberately restricted interval model."""
import math
from statistics import mean, median, variance
from foundation_project import finite

def summarize(values):
    values = [finite(v) for v in values]
    if len(values) < 2:
        raise ValueError("at least two observations required")
    return {"n": len(values), "mean": mean(values), "median": median(values),
            "sample_variance": variance(values)}

def conditional_count(joint, conditioned):
    if (type(joint) is not int or type(conditioned) is not int
            or conditioned <= 0 or not 0 <= joint <= conditioned):
        raise ValueError("valid counts and nonempty condition required")
    return joint / conditioned

def known_sigma_interval(average, sigma, n):
    average, sigma = finite(average), finite(sigma)
    if sigma < 0 or type(n) is not int or n <= 0:
        raise ValueError("nonnegative sigma and positive integer n required")
    margin = 1.96 * sigma / math.sqrt(n)
    return average - margin, average + margin

if __name__ == "__main__":
    print(summarize([10,10,10,10,100]))
    print(round(conditional_count(8,17),4))
    print(known_sigma_interval(50,10,100))

"""Small real-vector operations, with explicit shape validation."""
import math
from foundation_project import finite

def vector(values):
    result = [finite(v) for v in values]
    if not result:
        raise ValueError("nonempty vector required")
    return result

def dot(left, right):
    left, right = vector(left), vector(right)
    if len(left) != len(right):
        raise ValueError("matching dimensions required")
    return sum(a*b for a,b in zip(left,right))

def matvec(matrix, values):
    values = vector(values)
    rows = [vector(row) for row in matrix]
    if not rows or any(len(row) != len(values) for row in rows):
        raise ValueError("nonempty rectangular matrix must match vector")
    return [dot(row,values) for row in rows]

def cosine(left, right):
    left, right = vector(left), vector(right)
    numerator = dot(left,right)
    denominator = math.sqrt(dot(left,left)) * math.sqrt(dot(right,right))
    if denominator == 0:
        raise ValueError("zero vector has no cosine direction")
    return numerator / denominator

if __name__ == "__main__":
    candidates = [[0.9,0.4],[0.6,0.8]]
    for weights in ([0.8,0.2],[0.5,0.5]):
        print([round(v,2) for v in matvec(candidates,weights)])
